using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.Invoices.Dtos;using Namaa.Domain.Common.Errors;using Namaa.Domain.Common.Results;namespace Namaa.Application.Invoices.Commands.AddInvoiceItem;public sealed class AddInvoiceItemCommandHandler(IInvoiceRepository repository,IApplicationDbContext db):IRequestHandler<AddInvoiceItemCommand,Result<InvoiceItemDto>>{public async Task<Result<InvoiceItemDto>>Handle(AddInvoiceItemCommand request,CancellationToken cancellationToken){var e=await repository.FindForUpdateAsync(request.InvoiceId,cancellationToken);if(e is null)return Result.Failure<InvoiceItemDto>(InvoiceErrors.NotFound);if(e.Status.ToString()!="Draft")return Result.Failure<InvoiceItemDto>(InvoiceErrors.NotDraft);var i=e.AddItem(request.Description,request.Quantity,request.UnitPrice,request.DiscountAmount,request.TaxAmount,request.ServiceId);await db.SaveChangesAsync(cancellationToken);return Result.Success(InvoiceItemDto.FromEntity(i));}}
